(97791, 1547, 'mp_2_1_text', '写真ではわかりにくいと思いますが・・・・<br> 屋根材にはコロニアルという素材が使われていました。<br>コロニアルは初期投資はお値打ちというメリットがある一方で、<br>メンテナンスの必要な素材でもあります。 <br>一目で、色落ちは把握できました。めくれや欠けはないようです。<br>またコケは付いていませんでした。<br>'),
(49045, 1551, '_wp_attached_file', 'IMG_2275.jpg'),
(49046, 1551, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:320;s:6:"height";i:240;s:4:"file";s:12:"IMG_2275.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:20:"IMG_2275-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:20:"IMG_2275-300x225.jpg";s:5:"width";i:300;s:6:"height";i:225;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
(49047, 1551, '_wp_attachment_image_alt', '屋根塗装メンテナンス'),
(97814, 1547, 'mp_5_type', 'texts'),
(97815, 1547, 'mp_5_rail', '5'),
(97807, 1547, 'mp_3_type', 'columns'),
