(60847, 1734, '_wp_attached_file', '5554ea89987df9fc007695e3fc59706c.jpg'),
(60848, 1734, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:320;s:6:"height";i:240;s:4:"file";s:36:"5554ea89987df9fc007695e3fc59706c.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"5554ea89987df9fc007695e3fc59706c-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"5554ea89987df9fc007695e3fc59706c-300x225.jpg";s:5:"width";i:300;s:6:"height";i:225;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
(60849, 1734, '_wp_attachment_image_alt', 'ボッシュ調理機器'),
(97230, 1729, 'mp_1_1_text', '今日は、名古屋市熱田区にある <span style="background-color: rgb(204, 204, 204);">「真野工業株式会社」</span> さんのショールームへ行っていきました！<br>オーダーキッチンを取り扱う自社は、輸入機器について製品の知識を深めるために、<br>この様な商品発表会などで実際に製品に触れ、実演を見たりして、体感することを大切にしています。<br>'),
(141611, 3706, '_edit_lock', '1487746422:24'),
(97231, 1729, 'mp_1_type', 'texts'),
(97232, 1729, 'mp_1_rail', '1'),
(97233, 1729, 'mp_2_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/5d67cb180f9371fb1785f760bdd37052.jpg'),
(97234, 1729, 'mp_2_1_href', ''),
(97235, 1729, 'mp_2_1_target', ''),
(97236, 1729, 'mp_2_1_style', ''),
(97237, 1729, 'mp_2_1_suffix', ''),
(97238, 1729, 'mp_2_1_text', '<b>ＢＯＳＣＨ</b>と言えば、日本では電気工具メーカーの認知度が<br>強いでしょうか。<br><br>私も知らなかったことですが、<br>２０年くらい前までの輸入食洗機と言えば<b>ＢＯＳＣＨ</b>が<br>一番人気だったとのことです。<br>また、海外でのシェアは多いとのこと。<br>勉強会に行かないとわからないこともあります。<br>'),
(61093, 1737, '_wp_attached_file', '1c5b6b91955eec2a545665fea5ad5cfe.jpg'),
(61094, 1737, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:320;s:6:"height";i:240;s:4:"file";s:36:"1c5b6b91955eec2a545665fea5ad5cfe.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"1c5b6b91955eec2a545665fea5ad5cfe-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"1c5b6b91955eec2a545665fea5ad5cfe-300x225.jpg";s:5:"width";i:300;s:6:"height";i:225;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
(61095, 1737, '_wp_attachment_image_alt', '実食'),
(97267, 1729, 'mp_5_type', 'texts'),
(97268, 1729, 'mp_5_rail', '5'),
(97269, 1729, 'mp_6_1_text', '<hr><br><b><font color="#663300">新築、建て替え、リフォーム、オーダーキッチンは<br>\r\n‘遊び心いっぱいの空間づくり’を得意とする　遊建築工房へ</font></b><br>\r\n<br>\r\n遊 建築工房<br>\r\nフリーダイヤル： <span class="tel-link">0120-799-878</span> 　（※機種によってフリーダイヤルをご利用いただけない場合あり）<br>\r\nTEL： <span class="tel-link">052-883-8854</span> ／FAX：052-883-8864(24時間受付)<br>\r\n営業時間：8：00～19：00<br>主な施工エリア：名古屋市緑区・名古屋市内・日進市・刈谷市・大府市・東海市・知多市・阿久比町ほか<br>'),
