(66364, 1792, '_wp_attached_file', '9abdd8f001cd7759fa2f8d0bb925b8f3.jpg'),
(66365, 1792, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:240;s:6:"height";i:320;s:4:"file";s:36:"9abdd8f001cd7759fa2f8d0bb925b8f3.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"9abdd8f001cd7759fa2f8d0bb925b8f3-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"9abdd8f001cd7759fa2f8d0bb925b8f3-225x300.jpg";s:5:"width";i:225;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
(66366, 1792, '_wp_attachment_image_alt', '玄関ドア取り換え'),
(86004, 1790, 'mp_1_type', 'columns'),
(86005, 1790, 'mp_1_columns', '1'),
(86006, 1790, 'mp_1_rail', '1'),
(86000, 1790, 'mp_1_1_target', ''),
(86001, 1790, 'mp_1_1_style', ''),
(86002, 1790, 'mp_1_1_suffix', ''),
(86003, 1790, 'mp_1_1_text', '<font color="#666666"><b><br><br>「玄関ドアのお見積り依頼」</b></font>をいただきましたので、現場確認してきました。\r\n<br>パッと見た目きれいに見える玄関ドアですが、近くで見ると白い斑点があちこちにあります。\r\n<br>材質はアルミ製ですので、この白い斑点は錆かと思います。<br> お客様にとっては、毎日出入りする玄関ドアですので白い斑点を目にする機会も多く、<br>だんだんと汚れてきたな～と不快に感じられているようです<img src="http://www.yu-3.jp/smileys/bearing.gif"><br><br><br>こちらの住宅　外壁はタイルですので、ベストの方法は<u>、ドアの枠を残して、ドアを交換する方法</u>です。<br>また、別の方法として、「カバー工法」が考えられます。<br>「カバー工法」は、<u>既存のドア枠の上に、カバーの枠を付けドアを交換する工法</u>のことです。<br>費用面では、後者の方が割高にはなります。<br><br><br>２０年前と比較すると、各メーカー共通して、鍵の防犯性の向上が特徴的です。<br>キーレスでドアの鍵を開け閉めできたり、ヒッキングに強い構造など、<br>デザインの一新だけでなくメリットが得られる玄関ドア交換リフォームです<img src="http://www.yu-3.jp/smileys/sign03.gif"><br><br>家の顔になる玄関ドアリフォームは、大がかりな工事でなく、通常工期１日もお客様にとっては魅力でないでしょうか。<br><br><br><br><br><br>'),
(66491, 1790, '_wp_old_slug', '%e7%8e%84%e9%96%a2%e3%83%89%e3%82%a2%e4%ba%a4%e6%8f%9b%e3%81%ae%e3%81%8a%e8%a6%8b%e7%a9%8d%e3%82%8a%e4%be%9d%e9%a0%bc%e3%80%80%e3%80%80%e5%90%8d%e5%8f%a4%e5%b1%8b%e5%b8%82%e7%b7%91%e5%8c%ba'),
