INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(98431, 1044, 'mp_2_1_text', '<span style="color: #999999;" data-mce-style="color: #999999;"><span style="color: #000000;" data-mce-style="color: #000000;"><span style="font-size: small;" data-mce-style="font-size: small;"><span style="color: #ff0000;" data-mce-style="color: #ff0000;"><span style="color: #666666;" data-mce-style="color: #666666;">広々としたお子様の遊び場があります。<br><br></span></span></span></span></span><span style="color: #999999" data-mce-style="color: #999999;"><span style="color: #000000" data-mce-style="color: #000000;"><span style="font-size: small" data-mce-style="font-size: small;">今日の打ち合わせは時間がかかりそうだ・・と予想されるときには、お菓子作りや、工作体験などして、子供たちも楽しく待ちます。</span></span></span><span style="color: #999999;" data-mce-style="color: #999999;"><span style="color: #000000;" data-mce-style="color: #000000;"><span style="font-size: small;" data-mce-style="font-size: small;"><span style="color: #ff0000;" data-mce-style="color: #ff0000;"><span style="color: #666666;" data-mce-style="color: #666666;"></span></span></span></span></span><br>'),
