(98424, 1044, 'mp_1_type', 'texts'),
(98425, 1044, 'mp_1_rail', '1'),
(72332, 613, '_wp_attachment_image_alt', 'スライム作り'),
(98442, 1044, 'mp_3_type', 'texts'),
