(525694, 90, 'mp_9_1_style', ''),
(525695, 90, 'mp_9_1_suffix', ''),
(525696, 90, 'mp_9_1_text', '<div align="center"><font size="2">ステンレスキッチン</font><font size="1"><font size="2">※</font><br><br><br><br><br><br></font></div>'),
