INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(100278, 1027, 'mp_1_1_text', '<span style="color: #ff9933;"></span><br><div><span style="color: #999999;"><span style="color: #000000;"><br></span></span></div><div><span style="color: #999999;">\r\n<span style="color: #000000;">\r\n週末は、お客様との打ち合わせがあります。</span></span>&nbsp;</div><div><span style="color: #999999;"><span style="color: #000000;">弊社のお客様の多くが子連れファミリーということもあり、お子様が退屈されないように楽しい企画満載です♪</span></span>&nbsp;</div><div><br></div><div><span style="color: #999999;"><span style="color: #000000;">先日は、小学生、未就園児のお子さんとクッキーづくりをしました！！</span></span></div><div><span style="color: #999999;"><span style="color: #000000;"><b><span style="color: #ff0000;"><br></span></b></span></span></div><div>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n<b><span style="color: #ff0000;">↓モデルハウスのキッチンにて</span></b></span></span></div><div>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\n<a id="i13665634460" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8c3796ee.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8c3796ee.jpg" alt="" border="0"></a></span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;"> <span style="color: #666666; font-size: small;">\r\n<a id="i13665634937" class="detailOn" href="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8c3e6898.jpg"><img src="http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8c3e6898.jpg" alt="" border="0"></a></span></span></span>&nbsp;</div><div><br></div><div><span style="color: #999999;"><span style="color: #000000;"><span style="color: #666666; font-size: small;"><span style="color: #000000;">打ち合わせには平均で２時間くらいのお時間を頂戴しています。</span></span></span></span>&nbsp;</div><div><span style="color: #999999;"><span style="color: #000000;"><span style="color: #666666; font-size: small;"><span style="color: #000000;">お子さんが楽しんでいる間に、ご両親様は打ち合わせに励んでいただけます。</span></span></span></span></div><div><span style="color: #999999;"><span style="color: #000000;">子どもたちが、「また、来たい！」「もっと遊んでいたい！！」</span></span>\r\n\r\n<span style="color: #999999;"><span style="color: #000000;">\r\nその様に言ってくれると、みんなハッピーですね♪<br><br><br></span></span><span style="color: #ff0000;"></span></div>'),
(100281, 1027, 'mp_2_1_text', '<hr><br><b><font color="#663300">新築、建て替え、リフォーム、オーダーキッチンは<br>\r\n‘遊び心いっぱいの空間づくり’を得意とする　遊建築工房へ</font></b><br>\r\n<br>\r\n遊 建築工房<br>\r\nフリーダイヤル： <span class="tel-link">0120-799-878</span> 　（※機種によってフリーダイヤルをご利用いただけない場合あり）<br>\r\nTEL： <span class="tel-link">052-883-8854</span> ／FAX：052-883-8864(24時間受付)<br>\r\n営業時間：8：00～19：00<br>主な施工エリア：名古屋市緑区・名古屋市内・日進市・刈谷市・大府市・東海市・知多市・阿久比町ほか<br>'),
