(101417, 1019, 'mp_2_type', 'texts'),
(99059, 1019, '_wp_old_slug', '%e3%82%ad%e3%83%83%e3%83%81%e3%83%b3%e9%83%a8%e6%9d%90%e4%ba%a4%e6%8f%9b%e3%80%80%e6%8f%9b%e6%b0%97%e6%89%87%e3%83%bb%e3%82%ac%e3%82%b9%e3%82%b3%e3%83%b3%e3%83%ad%e3%83%bb%e9%a3%9f%e6%b4%97%e6%a9%9f'),
(101416, 1019, 'mp_2_1_text', '<span style="color: #999999;"><span style="color: #000000;">キッチンリフォームを得意としている弊社ですが、キッチンまるごと入れ替えだけでなく、<b>部材交換も対応</b>できます！</span></span>\r\n\r\n<span style="color: #999999;"><span style="text-decoration: underline;"><b>\r\n</b></span><span style="color: #000000;"><br>予算に合わせてご選択いただければと思います。<br>名古屋市天白区にて、キッチンリフォームを行いました。<br><br><br></span></span>'),
(103633, 1018, 'mp_3_type', 'columns'),
(103634, 1018, 'mp_3_columns', '3'),
(103632, 1018, 'mp_3_3_text', '戸外からも、家からも行き来が可能です。<br><br>'),
(103631, 1018, 'mp_3_3_suffix', ''),
