(107206, 1010, 'mp_4_1_text', '<br>'),
(107207, 1010, 'mp_4_2_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf8a0e35b2.jpg'),
(107208, 1010, 'mp_4_2_href', ''),
