(110554, 1005, 'mp_contents', '1'),
(110547, 1005, 'mp_4_1_text', '<span style="font-size: 10pt;">外壁シュミ</span><span style="font-size: 10pt;">レーションもしてみました。</span><div style="font-weight: normal;"><span style="font-size: 10pt;"><br>サイディングだとメンテナンスはどうなの？という声もよく聞かれますが、</span><b style="font-size: 10pt;">\r\n<font color="#666666">色褪せに強いプラチナコート、雨で汚れを洗い落すマイクロガード、\r\n火災に強い耐火4等級など、</font>\r\n</b><span style="font-size: 10pt;">優れた性能を持ち合わせたサイディングをご選択いただけます。</span></div><br><br><br>'),
(110546, 1005, 'mp_4_1_suffix', ''),
(110539, 1005, 'mp_3_type', 'simple'),
(110540, 1005, 'mp_3_float', 'left'),
(110541, 1005, 'mp_3_rail', '3'),
