(110531, 1005, 'mp_2_type', 'texts'),
(110532, 1005, 'mp_2_rail', '2'),
(110533, 1005, 'mp_3_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/blog_import_57bbf895623e9.jpg'),
