INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(111171, 936, 'mp_1_1_text', '<font color="#FF9933">こんにちは、遊建築工房です。</font><span><br><br>2014年もあと少しで終わり・・・\r\n今年は10周年の節目の年でもありました。\r\n<br><br>1年を振り返ってみると、\r\n家づくり塾が定着し、色々な相談が持ちかけられました。\r\n<br><br>また、キッチンマイスターの資格も取りました！<br>忙しかったですが、大変充実した1年になりました。<br><br>さて、弊社の<font color="#FF0000"><u>お正月休み</u></font>は\r\n<font color="#FF0000"><b>1月1日～1月3日</b></font>とさせて頂きます。\r\nこの間も、メールとフリーダイヤルは繋がります。<br><br>それでは、良いお年をお迎えください。</span>'),
(111170, 936, '_wp_old_slug', '%e3%81%8a%e6%ad%a3%e6%9c%88%e4%bc%91%e3%81%bf%e3%81%ae%e3%81%8a%e7%9f%a5%e3%82%89%e3%81%9b'),
