(128962, 3360, '_wp_attachment_image_alt', '対面キッチン'),
(201707, 3359, 'mp_1_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/01f2e090a36fb3b76d15214f6f151d90.jpg'),
