(135416, 3588, 'mp_2_type', 'columns'),
(135415, 3588, 'mp_2_2_text', '<font color="#990000">メールでのやりとりは頻繁に②\r\n\r\n\r\n</font><br><br><b>お客様から弊社へ\r\n</b><br>疑問に思ったことや、わからない点など、お客様より質問を頂戴します。<br><br><br><br><br><br>'),
(135414, 3588, 'mp_2_2_suffix', ''),
