(159645, 3807, 'mp_3_rail', '3'),
(159646, 3807, 'mp_4_1_text', '<hr><br><b><font color="#663300">新築、建て替え、リフォーム、オーダーキッチンは<br>\r\n‘遊び心いっぱいの空間づくり’を得意とする　遊建築工房へ</font></b><br>\r\n<br>\r\n遊 建築工房<br>\r\nフリーダイヤル： <span class="tel-link">0120-799-878</span> 　（※機種によってフリーダイヤルをご利用いただけない場合あり）<br>\r\nTEL： <span class="tel-link">052-883-8854</span> ／FAX：052-883-8864(24時間受付)<br>\r\n営業時間：8：00～19：00<br>主な施工エリア：名古屋市緑区・名古屋市内・日進市・刈谷市・大府市・東海市・知多市・阿久比町ほか<br>'),
(159330, 3811, '_wp_attached_file', '72a0848af488b99a45317780a86ac175.jpg'),
(159331, 3811, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:240;s:6:"height";i:320;s:4:"file";s:36:"72a0848af488b99a45317780a86ac175.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"72a0848af488b99a45317780a86ac175-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"72a0848af488b99a45317780a86ac175-225x300.jpg";s:5:"width";i:225;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
