(162413, 3856, 'mp_2_2_style', ''),
(162414, 3856, 'mp_2_2_suffix', ''),
(162415, 3856, 'mp_2_2_text', '滑り台やトンネルの遊具は、そのまま利用します。'),
(162416, 3856, 'mp_2_3_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/abc717a537495905132bd50a4a654dd7.jpg'),
