(165014, 3919, 'mp_1_type', 'texts'),
(165015, 3919, 'mp_1_rail', '1'),
(165016, 3919, 'mp_2_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/e31bfb5cae3dbb710907a3287ab2df19.jpg'),
