(173910, 4156, '_wp_attached_file', '1de7ff0181cbca3a0db535bb91793aa4.jpg'),
(173709, 4134, 'mp_1_1_text', '岡崎市の<span style="background-color: rgb(204, 204, 204);">マンション</span>で、<span style="background-color: rgb(204, 204, 204);">内装リフォーム</span>が始まりました。<br><span style="background-color: rgb(204, 204, 204);">和室から洋室にチェンジ</span>する内容です。<br>６畳の部屋で、工期は５日ほどかかりますが、解体の作業からスタートしました。<br><br><br><br>'),
(173710, 4134, 'mp_1_type', 'texts'),
(173711, 4134, 'mp_1_rail', '1'),
(173712, 4134, 'mp_2_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/30e2e62da8a5f1d56594c146695d56da.jpg'),
