(179509, 4259, 'mp_2_1_suffix', ''),
(179510, 4259, 'mp_2_1_text', '張替えの部分だけ、既存の外壁の解体です。<br><br><br><br><br><br><br><br><br><br>\r\n\r\n\r\n'),
