INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(179349, 4264, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:240;s:6:"height";i:320;s:4:"file";s:36:"1f9dde1d97dfc49a96dbf406b8e8fb35.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"1f9dde1d97dfc49a96dbf406b8e8fb35-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"1f9dde1d97dfc49a96dbf406b8e8fb35-225x300.jpg";s:5:"width";i:225;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
(179350, 4264, '_wp_attachment_image_alt', '外壁部分張替え　解体作業'),
(179525, 4259, 'mp_4_rail', '4'),
(179526, 4259, 'mp_contents', '1'),
(179524, 4259, 'mp_4_type', 'texts'),
(179517, 4259, 'mp_2_type', 'columns'),
(179518, 4259, 'mp_2_columns', '2'),
(179519, 4259, 'mp_2_rail', '2'),
(179520, 4259, 'mp_3_1_text', 'サイディングはデザインの種類も豊富です。<br>部分的に張替えても、家のイメージは変わります。<br>イメージをガラッと変えたい！、イメージを少しだけ変えたい！サイディングのデザインは豊富ですので、どちらにも対応できます。<br>仕上がりをお楽しみに<img src="http://www.yu-3.jp/smileys/happy01.gif"><br>'),
(179521, 4259, 'mp_3_type', 'texts'),
