(189307, 4312, 'mp_2_columns', '1'),
(189308, 4312, 'mp_2_rail', '2'),
(189298, 4312, 'mp_1_type', 'texts'),
(189305, 4312, 'mp_2_1_text', '<b>ユニットバス設置完了</b><br>ビニールなどで保護してあるので、見にくいですが・・・<br><br><br>'),
