(191187, 4523, 'mp_2_1_suffix', ''),
(191188, 4523, 'mp_2_1_text', '<b><font color="#990000">ＡＦＴＥＲ</font><br>天井板　ジプトーンの張替えと、照明器具をＬＥＤへ</b>'),
(191189, 4523, 'mp_2_type', 'simple'),
