(193171, 4585, '_wp_attachment_image_alt', '外壁部分塗装　ＢＥＦＯＲＥ'),
(193722, 4580, 'mp_6_1_text', '<hr><br><b><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」<br>\r\n新築、建て替え、リフォーム、オーダーキッチンは、遊建築工房へ</font></b><br>\r\n<br>\r\n遊 建築工房<br>\r\nフリーダイヤル： <span class="tel-link">0120-799-878</span> 　（※機種によってフリーダイヤルをご利用いただけない場合あり）<br>\r\nTEL： <span class="tel-link">052-883-8854</span> ／FAX：052-883-8864(24時間受付)<br>\r\n営業時間：8：00～19：00<br>主な施工エリア：名古屋市緑区・名古屋市内・日進市・刈谷市・大府市・東海市・知多市・阿久比町ほか<br>'),
(193721, 4580, 'mp_5_rail', '5'),
(193720, 4580, 'mp_5_type', 'texts'),
(193258, 4587, '_wp_attached_file', '51997501274dc4c716d9468423e681a41.jpg'),
(193259, 4587, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:240;s:6:"height";i:320;s:4:"file";s:37:"51997501274dc4c716d9468423e681a41.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:45:"51997501274dc4c716d9468423e681a41-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:45:"51997501274dc4c716d9468423e681a41-225x300.jpg";s:5:"width";i:225;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
(193260, 4587, '_wp_attachment_image_alt', '外壁部分塗装'),
(193689, 4580, 'mp_1_1_text', '名古屋市緑区近郊　豊明市の<span style="background-color: rgb(204, 204, 204);">戸建住宅</span>にて、<span style="background-color: rgb(204, 204, 204);">外壁の部分塗装</span>が完了しました。<br><br>部分塗装とは、家一軒を丸ごと塗装するのではなく、部分的に塗装をすることです。<br>今回のお宅では、壁の3面は鉄板系の外壁であり、残りの1面が塗り壁でした。<br><br>'),
(193299, 4588, '_wp_attached_file', '40c51940852ee7d382ee7b0f7e77b7d9.jpg'),
(193300, 4588, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:234;s:6:"height";i:320;s:4:"file";s:36:"40c51940852ee7d382ee7b0f7e77b7d9.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"40c51940852ee7d382ee7b0f7e77b7d9-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"40c51940852ee7d382ee7b0f7e77b7d9-219x300.jpg";s:5:"width";i:219;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
