(204845, 4884, 'mp_2_1_suffix', ''),
(204846, 4884, 'mp_2_1_text', '<b>①廊下のフローリングの張替え相談</b>'),
(204847, 4884, 'mp_2_2_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/61ad8ff37c91a88a0e039a04f2051b2f.jpg'),
