(207794, 4968, 'mp_2_1_style', ''),
(207795, 4968, 'mp_2_1_suffix', ''),
(207796, 4968, 'mp_2_1_text', '<b><font color="#990000">タイルミックス貼り</font><br><br><br></b>「細部にまでこだわりたい！！」<br>お客様のご要望に対応しています。<b><br><br></b><br>普通に貼るより、表情が出ました。<b><br><br><br></b>'),
(207797, 4968, 'mp_2_type', 'simple'),
(207798, 4968, 'mp_2_float', 'left'),
(207799, 4968, 'mp_2_rail', '2'),
