(503093, 7637, 'mp_5_1_text', '<iframe src="https://www.youtube.com/embed/cU7raxH3j8I" allow="accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture" allowfullscreen="" width="100%" height="500" frameborder="0"></iframe>\r\n<a href="https://youtu.be/cU7raxH3j8I" target="_blank">■動画が再生されない方はコチラ■</a>'),
(503094, 7637, 'mp_5_type', 'texts'),
(503095, 7637, 'mp_5_rail', '5'),
(503096, 7637, 'mp_6_1_text', '<hr><br><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font></span><b><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300"><br><font size="4">外構リフォーム、庭づくりは遊建築工房へ</font></font></span></b><br>\r\n<br>\r\n<br><font size="3" color="#cc6600"><font color="#000000">【　</font>&gt;&gt;お問い合わせ 各種相談会はこちら&lt;&lt; </font><font size="3">よりお問い合わせください。】</font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font><br>'),
