(506434, 7532, 'mp_2_1_text', '<div><b><font size="5"><span style="background-color: rgb(204, 204, 204);"><br></span></font></b></div><div><b><font size="5"><span style="background-color: rgb(204, 204, 204);">隣家との幅が狭い外壁塗装　名古屋市緑区<br></span></font></b></div><div><br></div><div><br></div><div>隣家と接近している住宅で、足場の設置がお隣さんの敷地にはみ出すケースです。</div><div>名古屋市内ではこのような住環境も多いです。</div><div>工事を進めるに当たっては、お隣さんの承諾が必要となってきます。</div><div><br></div><div><br></div><br><div><br></div><div><br></div>'),
(328750, 7534, '_wp_attachment_image_alt', 'AFETR外壁塗装'),
(506477, 7532, 'mp_8_1_text', '<hr><br><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font></span><b><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300"><br>\r\n<font size="4">外壁塗装、屋根、雨とい交換など家の外回りのリフォームは、遊建築工房へ</font></font></span></b><br>\r\n<br>\r\n<br><font size="3" color="#cc6600"><font color="#000000">【</font>　>>お問い合わせ 各種相談会はこちら<< </font><font size="3">よりお問い合わせください。】</font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font><br>'),
(506476, 7532, 'mp_7_rail', '7'),
(328749, 7534, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:320;s:6:"height";i:290;s:4:"file";s:36:"c4756ba5ee33028f114ae9b11b472b55.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"c4756ba5ee33028f114ae9b11b472b55-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"c4756ba5ee33028f114ae9b11b472b55-300x271.jpg";s:5:"width";i:300;s:6:"height";i:271;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
