INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(506745, 7499, 'mp_5_1_text', '<hr><br><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font></span><b><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300"><br>\r\n<font size="4">キッチンのパーツ交換、キッチンリフォームは遊建築工房へ</font></font></span></b><br>\r\n<br>\r\n<br><font size="3" color="#cc6600"><font color="#000000">【</font>　>>お問い合わせ 各種相談会はこちら<< </font><font size="3">よりお問い合わせください。】</font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font><br>'),
(327035, 7503, '_wp_attachment_image_alt', 'アリアフィーナ　レンジフード'),
(506738, 7499, 'mp_3_1_text', '<div align="center">横壁付けのレンジフードです。</div><div align="center">上の施工は、右壁付けですが、左壁付けもあります。 <br></div><div align="center"><br></div><div align="center">カラーは、テクスチャーブラック色。</div><div align="center">マットな塗装がシックな内装に合いました。</div><div align="center"><br></div><div align="center"><br></div><div align="center">お手入れの際、シロッコファンの脱着などしたいですが、ワンタッチで簡単です。</div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div>'),
