(353665, 7243, 'mp_1_type', 'texts'),
(353666, 7243, 'mp_1_rail', '1'),
(353667, 7243, 'mp_2_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/65162f817730fbeedf7645dbb0ea64eb.jpg'),
(353668, 7243, 'mp_2_1_href', ''),
(353669, 7243, 'mp_2_1_target', ''),
(353670, 7243, 'mp_2_1_style', ''),
(353671, 7243, 'mp_2_1_suffix', ''),
(353672, 7243, 'mp_2_1_text', '<div align="center"><font size="1" color="#333333">※画像　「大建工業株式会社 | 2018-19 部位別カタログ 分冊１： 床材 床暖房」より引用</font></div><div align="center"><font size="1" color="#333333"><br></font></div><div align="center"><font size="1" color="#333333"><br></font></div><div align="center"><font size="1" color="#333333"><font size="2">こちらの床暖房対応の上張り可能なフローリングですと、厚みは３．５ｍｍ。</font></font></div><div align="center"><font size="1" color="#333333"><font size="2">他メーカーも厚み薄の床材で、上張り用フローリングのラインナップがあります。<br></font></font></div><div align="center"><font size="1" color="#333333"><font size="2"><br></font></font></div><div align="center"><font size="1" color="#333333"><font size="2">とは言え、敷居など段差を感じやすい部分での段差対策、納まり部材が必要な場合もあります。</font></font></div><div align="center"><font size="1" color="#333333"><font size="2">また、既存の床がきしんだり沈んだりする場合は、下地に原因があるので要注意。</font></font></div><div align="center"><font size="1" color="#333333"><font size="2">「上張り希望」でプロにご相談下さい<img src="http://www.yu-3.jp/smileys/happy01.gif"><br></font></font></div>'),
(353664, 7243, 'mp_1_1_text', '<div>住宅建材は日進月歩しています。</div><div><span style="background-color: rgb(204, 204, 204);">フローリングの張替え</span>に、工事簡易＆短縮できる<font color="#333333"><b>上張り（重張り）仕様の床材</b></font>があります。</div><div>床暖房の床でも、上張り出来る商品もあります。</div><div><br></div><div><br></div>'),
(314522, 7247, '_wp_attachment_image_alt', 'ＤＡＩＫＥＮ　床材');
