(303303, 7026, 'mp_excerpt', ''),
(355804, 7017, 'mp_1_type', 'texts'),
(355805, 7017, 'mp_1_rail', '1'),
(355806, 7017, 'mp_2_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/39c3f63ebe9ce77ca14d4c84e79c8751.jpg'),
(355816, 7017, 'mp_3_type', 'texts'),
(355817, 7017, 'mp_3_rail', '3'),
(355818, 7017, 'mp_contents', '1'),
(355849, 6998, 'mp_1_1_text', '<div>名古屋市千種区の<span style="background-color: rgb(204, 204, 204);">マンションリフォーム</span>がスタートしました。</div><div>新しい入居者様を見つけるための、リフォーム。</div><div>ただ設備や壁を新しくするだけでない、インテリアコーディネーターとタッグを組んだリノベーション。</div><div><br></div><div><br></div><div><br></div><div>工事の様子をご覧下さい。</div><div><br></div><div><br></div>'),
(303000, 7019, '_wp_attachment_image_alt', 'ＩＨクッキングヒーター取替え'),
(302999, 7019, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:240;s:6:"height";i:320;s:4:"file";s:36:"39c3f63ebe9ce77ca14d4c84e79c8751.jpg";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:44:"39c3f63ebe9ce77ca14d4c84e79c8751-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:44:"39c3f63ebe9ce77ca14d4c84e79c8751-225x300.jpg";s:5:"width";i:225;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
