(358047, 6784, 'mp_2_type', 'headlines'),
(358048, 6784, 'mp_2_rail', '2'),
(358049, 6784, 'mp_3_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/d76d63507837e4ab7a4e59788c422c67.jpg'),
