(286463, 6740, 'mp_excerpt', ''),
(358701, 6726, 'mp_9_type', 'texts'),
(358702, 6726, 'mp_9_rail', '9'),
(358703, 6726, 'mp_contents', '1'),
(359120, 6694, 'mp_1_1_text', '名古屋市緑区の<span style="background-color: rgb(204, 204, 204);">玄関ドアの部分補修</span>の事例です。<br>ドアそのものは全く問題なし、鍵の動作もスムーズです。<br>ただ、<font color="#666666"><b>表面のシートが破れてしまいました</b></font>・・・・・<br><br>こんな時は、玄関ドアの交換をしなくても、<u>シート張替えの部分補修で解決</u>できます<img src="http://www.yu-3.jp/smileys/sign03.gif"><br><br><br><br><br><br>'),
(358651, 6726, 'mp_3_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/de2d28d70ebb7a2ec2348b36ac1aecc2.jpg'),
(358652, 6726, 'mp_3_1_href', ''),
(358644, 6726, 'mp_1_1_text', '名古屋市緑区の<span style="background-color: rgb(204, 204, 204);">外壁＆屋根塗装の工事</span>の様子です。<br>足場設置から工事はスタートし、洗浄、コーキング打ち替え、屋根塗装、外壁塗装と進んで行きます。<br>40坪ほどの戸建の場合、工期は雨の日に作業できないことも踏まえ3週間程度を想定下さい。<br><br><br><br><br><br><br>'),
(358645, 6726, 'mp_1_type', 'texts'),
(358646, 6726, 'mp_1_rail', '1'),
(358647, 6726, 'mp_2_1_name', 'strapline'),
(358648, 6726, 'mp_2_1_text', '工事の様子　①洗浄作業'),
(358649, 6726, 'mp_2_type', 'headlines'),
(358650, 6726, 'mp_2_rail', '2'),
(285655, 6732, '_wp_attachment_image_alt', 'コーキング打ち替え4'),
(358678, 6726, 'mp_5_3_target', ''),
(358679, 6726, 'mp_5_3_style', ''),
