(361582, 6490, 'mp_9_1_style', ''),
(361576, 6490, 'mp_8_1_text', '最初から小部屋で独立させた子ども部屋'),
(361577, 6490, 'mp_8_type', 'headlines'),
(361578, 6490, 'mp_8_rail', '8'),
