(365212, 6028, 'mp_5_type', 'columns'),
(249903, 6034, '_wp_attachment_image_alt', 'リビング収納家具'),
(365193, 6028, 'mp_3_1_text', '<div align="center"><b><font color="#990000">造りつけのリビング収納 Ⅰ</font></b><br><br><font color="#990000"><font color="#000000">・ウォールナット色の面材で箱を作り、アクセントにエコカッラトを施工</font></font><br><font color="#990000"><font color="#000000">・オープン棚は見せる収納、クローズ棚は隠す収納</font></font><br>・テレビの配線が見えないように、コンセント位置も計画<br></div><b><font color="#990000"><br><br><br><br><br></font></b>'),
