(378528, 5434, 'mp_2_1_text', '古い玄関ドアをはずし,枠はそのままで新しい玄関ドアを取り付け・・・・<br>'),
(378529, 5434, 'mp_2_2_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/2017-10-09-11.15.00-e1507531164175.jpg'),
(378530, 5434, 'mp_2_2_href', ''),
