(391501, 8989, '_wp_attachment_backup_sizes', 'a:5:{s:9:"full-orig";a:3:{s:5:"width";i:1920;s:6:"height";i:1440;s:4:"file";s:12:"IMG_3160.jpg";}s:14:"thumbnail-orig";a:4:{s:4:"file";s:20:"IMG_3160-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:11:"medium-orig";a:4:{s:4:"file";s:20:"IMG_3160-300x225.jpg";s:5:"width";i:300;s:6:"height";i:225;s:9:"mime-type";s:10:"image/jpeg";}s:10:"large-orig";a:4:{s:4:"file";s:21:"IMG_3160-1024x768.jpg";s:5:"width";i:1024;s:6:"height";i:768;s:9:"mime-type";s:10:"image/jpeg";}s:18:"full-1580702729912";a:3:{s:5:"width";i:1440;s:6:"height";i:1920;s:4:"file";s:27:"IMG_3160-e1580702719962.jpg";}}'),
(391502, 8989, '_wp_attachment_image_alt', '室内メーターボックス'),
