(549185, 86, 'mp_2_1_text', '「新しい家なら地震が来ても大丈夫」は本当か？'),
(549184, 86, 'mp_2_1_name', 'headline'),
(549183, 86, 'mp_1_rail', '1'),
(549182, 86, 'mp_1_columns', '1'),
(549181, 86, 'mp_1_type', 'columns'),
(549180, 86, 'mp_1_1_text', '<br><div align="left"><div><b><font size="4">いつ起こるかわからない地震に備えて、</font></b></div><div><b><br></b></div><div><b><font size="3">「evoltz エヴォルツ」は特許技術により他の制振装置よりも速く効き、</font></b></div><div><b><font size="3"><br></font></b></div><div><b><font size="4">あなたの家をいつまでも守ります。</font></b></div></div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div><div align="center"><br></div>'),
