(484588, 9340, 'mp_3_1_text', 'リノベーション工事の様子'),
(484589, 9340, 'mp_3_type', 'headlines'),
(484590, 9340, 'mp_3_rail', '3'),
(484591, 9340, 'mp_4_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/IMG_1336-e1597371875678.jpg'),
