(447728, 9387, '_wp_attachment_image_alt', '木とアイアインのキッチン'),
(513296, 9382, 'mp_contents', '1'),
(513287, 9382, 'mp_1_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/IMG_E1591-e1599541569361.jpg'),
