INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(485572, 9692, 'mp_11_1_text', '<div><b>\r\n</b><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font></span><b><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300"><br>\r\n<font size="4">水回りリフォーム：浴室、洗面、トイレは遊建築工房へ</font></font></span></b><font size="4"><br>\r\n</font><br>\r\n<br><font color="#cc6600">>>お問い合わせ 各種相談会はこちら<< </font>よりお問い合わせください。<br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font></div><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font><div style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal;"><br><br></div></div><hr><b>\r\n</b>'),
