(485735, 9605, 'mp_1_columns', '1'),
(485736, 9605, 'mp_1_rail', '1'),
(485737, 9605, 'mp_2_1_text', '<div><font color="#333333"><b><span style="background-color: rgb(204, 204, 204);"><font size="5" color="#000000">壁や出入り口ドアを設けて【個室】を作った事例</font></span><br></b></font></div><div><font color="#333333"><b><br></b></font></div><div><font color="#333333"><b><br></b></font></div><div><font color="#333333"><b>お子さんの受験や、中学に上がるタイミングで、子ども部屋を作ってあげたい！</b></font></div><div>そんな願いを叶えたリフォームです。</div><div>机とベッド+本棚くらいが置ける小さな空間ですが、出入り口も設け完全個室ができました。</div><br><div><br></div><div><br></div><div><br></div>'),
(485738, 9605, 'mp_2_type', 'texts'),
