(484516, 9362, 'mp_5_1_text', '<div>リノベーション予算350万円、工期1か月</div><div>・外壁塗装</div><div>・屋根塗装</div><div>・オーダーキッチン</div><div>・リビングダイニング内装</div><div>・トイレ</div><div>・洗面</div><div><br></div>'),
(484389, 9422, 'mp_1_1_href', ''),
(484390, 9422, 'mp_1_1_target', ''),
(484391, 9422, 'mp_1_1_style', ''),
(484392, 9422, 'mp_1_1_suffix', ''),
(484393, 9422, 'mp_1_1_text', '<br>'),
