(487388, 9073, 'mp_1_rail', '1'),
(487389, 9073, 'mp_2_1_text', '<div><font size="5"><span style="background-color: rgb(204, 204, 204);">名古屋市緑区のキッチン事例</span></font></div><div><font size="5"><span style="background-color: rgb(204, 204, 204);"><br></span></font></div><div><font size="5"><span style="background-color: rgb(204, 204, 204);"><font size="3"><span style="background-color: rgb(255, 255, 255);">ステンレスのシンクは丸みを帯びていないスクエア。</span></font><br></span></font></div><div><font color="#333333"><b>タッチレスの水洗金具</b></font>は、国内マーカー以外にも目を向けることで、お好みの水洗金具が見つかることもあります。</div><div><br></div><div><br></div><div><br></div>'),
(487390, 9073, 'mp_2_type', 'texts'),
(487391, 9073, 'mp_2_rail', '2'),
(487392, 9073, 'mp_3_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/5D3K0161-e1584948954317.jpg'),
