INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(487539, 9063, 'mp_9_1_text', '<div>・キッチンリフォーム</div><div>・オーダー家具</div><div>・内装リフォーム等</div><div><br></div><div><div align="left"><br></div><div align="left"><br></div><div align="left"><br></div><div align="left">始めは「オーダーなんて・・・」という考えだったお客様でしたが、</div><div align="left">自社の提案でオーダー製作でテレビボードを採用することになった事例です。<br>リビングの主役となって、また既製品にはない見た目で高級感をプラスしています。<br></div><div align="left">ご予算に合ったリノベーションのご提案をしていきます。</div><div align="left"><br></div><div align="left"><br></div><div align="left"><br></div><div align="left"><br></div><div align="left"><br></div><div align="left"><br></div><div><br></div><div><br><br></div></div>'),
(487541, 9063, 'mp_9_rail', '9'),
(487542, 9063, 'mp_10_1_text', '<hr><br><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font><b><font color="#663300"><br>\r\n<font size="4">リノベーション、オーダー家具、内装リフォームは、遊建築工房へ</font></font></b><br>\r\n<br><br><font size="3" color="#cc6600"><font color="#000000">【</font>　&gt;&gt;お問い合わせ 各種相談会はこちら&lt;&lt; </font><font size="3">よりお問い合わせください。】</font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font><div style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal; font-weight: normal;"><br><br></div></div>'),
