(490529, 8683, 'mp_3_1_name', 'strapline'),
(490530, 8683, 'mp_3_1_text', '～断熱リフォーム　施工の様子～'),
(490531, 8683, 'mp_3_type', 'headlines'),
(490532, 8683, 'mp_3_rail', '3'),
(490533, 8683, 'mp_4_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/2019-06-26-07.49.241-e1563234833796.jpg'),
