INSERT INTO `wp_23_postmeta` (`meta_id`, `post_id`, `meta_key`, `meta_value`) VALUES
(501493, 7686, 'mp_2_1_text', '<div><b><font size="5"><span style="background-color: rgb(204, 204, 204);"><br></span></font></b></div><div><b><font size="5"><span style="background-color: rgb(204, 204, 204);">名古屋市戸建　屋外手すり設置工事</span></font></b></div><div><font color="#666666"><b><br></b></font></div><div><font color="#666666"><b><br></b></font></div><div>玄関先に手すりの設置を行いました。</div><div>こちらは、介護リフォームではなく、段差からお子さんが落ちるのを防ぐための工事です。<br></div><div>夏に手すりが熱せられて握れない・・・というのを防ぐため、支柱はアルミ製ではあるものの、笠木にはシート加工がされている商品がありますので、そちらを推奨しました。</div><div><br></div><div><br></div><div><br></div><div><br></div>'),
(501484, 7686, 'mp_1_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/9334d575c16c531c9621234850f54289-e1616818868688.png'),
