(515427, 10102, 'mp_14_type', 'texts'),
(515428, 10102, 'mp_14_rail', '14'),
(515429, 10102, 'mp_contents', '1'),
(515426, 10102, 'mp_14_1_text', '<hr>\r\n<span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font></span><b><span style="font-family: Arial, Verdana; font-size: 10pt; font-style: normal; font-variant-ligatures: normal; font-variant-caps: normal;"><font color="#663300"><br>\r\n<font size="4">シロアリ駆除は遊建築工房へ</font></font></span></b><br>\r\n<br>\r\n<br><font size="3" color="#cc6600"><font color="#000000">【</font>　>>お問い合わせ 各種相談会はこちら<< </font><font size="3">　よりお問い合わせください。】</font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font>'),
(515424, 10102, 'mp_13_type', 'headlines'),
(515425, 10102, 'mp_13_rail', '13'),
(515423, 10102, 'mp_13_1_text', 'シロアリが活発に活動する春の時期以外でも、年中シロアリは増え続けています。羽ありを見かけたら、早めの措置を行ってください。'),
(515422, 10102, 'mp_13_1_name', ''),
(515420, 10102, 'mp_12_type', 'texts'),
(515421, 10102, 'mp_12_rail', '12'),
(515351, 10102, 'mp_1_1_text', '<div><span style="background-color: rgb(204, 204, 204);">名古屋市緑区にてシロアリ<span>相談</span></span>が寄せられました。</div><div><br></div><div>羽ありを庭の樹木の根本近くで見つけ、さらには玄関の土間でも見つけ、<br>「木造の家の土台とか大丈夫であろうか？」という内容でした。</div><div><br></div><div><br></div><div>ご相談をいただいた時期は5月の終わりで、</div><div>また発生場所から白ありの種類は、イエシロアリでないかと想定されました。</div><div>イエシロアリは、西日本に主に分布しています。</div><div>地中に大きな巣を作って生活するのが特徴です。</div><div><br></div><div>イエシロアリとの比較でヤマトシロアリがいますが、<br>日本全国に分布しており、水回りに被害が大きいのが特徴です。</div><div><br></div><div><br></div><div><br></div><div><br></div><div>シロアリ駆除は、日本シロアリ対策協会の安全管理基準をクリア―した薬品を用います。</div><div>施工には専門の技術をもった職人が散布をします。</div><div>普通の一般住宅であれば、施工日は1日は完了します。</div><div><br></div><div>人にもペットにも安全な駆除剤を採用していますが、<br>アレルギーや化学物質に敏感な体質の方は、事前に医師へご相談されることをお勧めします。</div><div><br></div><div><br></div><div><br></div><div><br></div><div><br></div>'),
(515431, 10116, '_wp_attached_file', 'spblog.png'),
(515432, 10116, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:640;s:6:"height";i:300;s:4:"file";s:10:"spblog.png";s:5:"sizes";a:2:{s:9:"thumbnail";a:4:{s:4:"file";s:18:"spblog-150x150.png";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:9:"image/png";}s:6:"medium";a:4:{s:4:"file";s:18:"spblog-300x140.png";s:5:"width";i:300;s:6:"height";i:140;s:9:"mime-type";s:9:"image/png";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
