(520561, 10180, 'mp_3_1_href', ''),
(520562, 10180, 'mp_3_1_target', ''),
(520889, 10190, 'mp_4_1_text', '<hr>\r\n<font color="#663300">暮らしを遊ぶ。これからの趣味は「家時間」</font><b><font color="#663300"><br><font size="4">タイル施工・室内塗装など内装リフォームは、遊建築工房へ</font></font></b><br>\r\n<br><br><font size="3" color="#cc6600"><font color="#000000">【</font>　>>お問い合わせ 各種相談会はこちら<< </font><font size="3">よりお問い合わせください。】</font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><font face="Arial, Verdana"><span style="font-size: 10pt;"></span></font><br><font face="Arial, Verdana"><span style="font-size: 10pt;"><br></span></font><div><font face="Arial, Verdana"><span style="font-size: 10pt;">主な施工エリア：</span><span style="font-size: 13.3333px;">名古屋市緑区・名古屋市天白区・名古屋市昭和区・名古屋市瑞穂区・名古屋市熱田区・</span></font><span style="font-size: 13.3333px; font-family: Arial, Verdana;">名古屋市港区・名古屋市南区・名古屋市千種区・名古屋市名東区・長久手市・日進市・</span><span style="font-size: 13.3333px; font-family: Arial, Verdana;">大府市・刈谷市・東海市・みよし市・東郷町・知立市・高浜市・阿久比町・半田市</span></div><font face="Arial, Verdana"><span style="font-size: 13.3333px;">※記載以外の地域はお問合せください。</span></font>'),
(520888, 10190, 'mp_3_rail', '3'),
(520887, 10190, 'mp_3_columns', '1'),
(520886, 10190, 'mp_3_type', 'columns'),
(520868, 10190, 'mp_1_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/50d54484c8d3f9bc66f610670b71b77f1-e1616804453112.png'),
