(523303, 10211, 'mp_2_1_text', '<span style="background-color: rgb(204, 204, 204);">豊明市の戸建てにて、造作洗面のリフォーム</span>が完了しました。<br><div>以前はTOTOの洗面台でしたが、深型のシンクやサンワカンパニーの水洗・ミラーなど機器やサイズ感などを吟味した結果・・・<br>使いやすく自分好みのオンリーワンの洗面台ができました。</div><div><br></div><div><br></div><div><br></div><div><br></div>'),
(522942, 10228, '_wp_attached_file', 'IMG_4676-e1636678281555.jpg'),
(522943, 10228, '_wp_attachment_metadata', 'a:5:{s:5:"width";i:300;s:6:"height";i:400;s:4:"file";s:27:"IMG_4676-e1636678281555.jpg";s:5:"sizes";a:3:{s:9:"thumbnail";a:4:{s:4:"file";s:20:"IMG_4676-150x150.jpg";s:5:"width";i:150;s:6:"height";i:150;s:9:"mime-type";s:10:"image/jpeg";}s:6:"medium";a:4:{s:4:"file";s:20:"IMG_4676-224x300.jpg";s:5:"width";i:224;s:6:"height";i:300;s:9:"mime-type";s:10:"image/jpeg";}s:5:"large";a:4:{s:4:"file";s:21:"IMG_4676-767x1024.jpg";s:5:"width";i:767;s:6:"height";i:1024;s:9:"mime-type";s:10:"image/jpeg";}}s:10:"image_meta";a:10:{s:8:"aperture";i:0;s:6:"credit";s:0:"";s:6:"camera";s:0:"";s:7:"caption";s:0:"";s:17:"created_timestamp";i:0;s:9:"copyright";s:0:"";s:12:"focal_length";i:0;s:3:"iso";i:0;s:13:"shutter_speed";i:0;s:5:"title";s:0:"";}}'),
