(522998, 10223, 'mp_contents', '1'),
(522997, 10223, 'mp_1_rail', '1'),
(522996, 10223, 'mp_1_float', 'left'),
(522995, 10223, 'mp_1_type', 'simple'),
(522989, 10223, 'mp_1_1_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/IMG_4676-e1636678281555.jpg'),
(522990, 10223, 'mp_1_1_href', ''),
