(523837, 10252, 'mp_2_1_text', '<br>'),
(523838, 10252, 'mp_2_2_image', 'http://www.yu-3.jp/wp-content/uploads/sites/23/0ca82bebfdede3c0a940ae7054206eef-e1639008015721.jpg'),
